
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_vcml_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_vcml", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.473070419713771e+00, -4.387654153899485e+00, -4.268046866237898e+00, -4.102530515328227e+00, -3.877345629805675e+00, -3.578372904491443e+00, -3.195090920965466e+00, -2.727926009731197e+00, -2.200859268175601e+00, -1.605360089283045e+00, -1.003837312476000e+00, -6.878586078172932e-01, -6.047721136843424e-01, -5.129307508235235e-01, -3.704469842526251e-01, -2.258284618896034e-01, -9.775589536300899e-02, -2.168377896212667e-02, -4.069881150063326e-03, -4.537192990642196e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


